<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{api}from'../../api';import{useSessionStore}from'../../stores/session';const session=useSessionStore(),bill=ref<any>();onShow(async()=>bill.value=await api.commissions(session.role))</script>
<template><view v-if="bill" class="page income-page"><view class="income-hero"><view class="income-hero__top"><view><text class="kicker">AUGUST INCOME</text><text class="label">本月预计收入</text></view><text class="bill-tag">月结</text></view><text class="amount"><small>¥</small>{{bill.payable}}</text><view class="trend"><view class="trend__bars"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></view><text>本周履约表现稳定</text></view></view><view class="breakdown card"><view><text>社群底薪</text><strong>¥{{bill.baseSalary}}</strong></view><view><text>配送提成</text><strong>¥{{bill.deliveryIncome}}</strong></view><view><text>跨期调整</text><strong>¥{{bill.adjustment}}</strong></view></view><view class="section-title"><view><text class="kicker green">DETAILS</text><text class="section-title__main">提成明细</text></view><text class="section-title__sub">共 {{bill.records.length}} 笔</text></view><view v-for="r in bill.records" :key="r.id" class="record card"><view class="record__mark"></view><view class="record__content"><text class="record__title">{{r.building}} 配送</text><text class="muted">{{r.orderNo}} · {{r.createdAt.slice(5,16).replace('T',' ')}}</text></view><text class="money">+¥{{r.amount}}</text></view></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.income-page{background:radial-gradient(circle at 90% 7%,rgba(185,242,39,.2),transparent 25%),$paper}.income-hero{position:relative;overflow:hidden;padding:36rpx;border-radius:38rpx;background:linear-gradient(145deg,$primary-deep,$primary-dark);color:#fff;box-shadow:0 18rpx 42rpx rgba(3,45,34,.22)}.income-hero:after{content:"";position:absolute;width:230rpx;height:230rpx;border-radius:50%;right:-80rpx;bottom:-110rpx;background:rgba(185,242,39,.1)}.income-hero text{display:block}.income-hero__top{display:flex;justify-content:space-between}.kicker{font-size:18rpx;letter-spacing:3rpx;color:$lime;font-weight:900}.label{font-size:24rpx;margin-top:8rpx;opacity:.78}.bill-tag{height:48rpx;padding:6rpx 18rpx;border:2rpx solid rgba(255,255,255,.24);border-radius:999rpx;font-size:20rpx}.amount{font-size:76rpx;line-height:1.1;font-weight:900;margin:22rpx 0}.amount small{font-size:32rpx;margin-right:8rpx}.trend{display:flex;align-items:flex-end;justify-content:space-between;font-size:19rpx;opacity:.76}.trend__bars{height:48rpx;display:flex;align-items:flex-end;gap:7rpx}.trend__bars i{width:8rpx;border-radius:8rpx;background:$lime}.trend__bars i:nth-child(1){height:16rpx}.trend__bars i:nth-child(2){height:28rpx}.trend__bars i:nth-child(3){height:22rpx}.trend__bars i:nth-child(4){height:38rpx}.trend__bars i:nth-child(5){height:31rpx}.trend__bars i:nth-child(6){height:45rpx}.trend__bars i:nth-child(7){height:40rpx}.breakdown{display:grid;grid-template-columns:repeat(3,1fr);margin-top:22rpx;padding:24rpx 10rpx}.breakdown>view{text-align:center}.breakdown>view+view{border-left:2rpx solid $line}.breakdown text,.breakdown strong{display:block}.breakdown text{font-size:19rpx;color:$muted}.breakdown strong{font-size:26rpx;margin-top:5rpx}.green{color:$primary}.record{display:flex;align-items:center;padding:24rpx;margin-bottom:16rpx}.record__mark{width:12rpx;height:54rpx;border-radius:8rpx;background:$lime;margin-right:18rpx}.record__content{flex:1}.record text{display:block}.record__title{font-weight:800}.record .muted{font-size:20rpx;margin-top:5rpx}.money{color:$primary-dark;font-size:30rpx;font-weight:900}</style>
